 import unittest
from candidate import pluck

class TestPluck(unittest.TestCase):
    def test_pluck_normalcase(self):
        self.assertEqual(pluck([4,2,3]), [2, 1])

    def test_pluck_empty_array(self):
        self.assertEqual(pluck([]), [])

    def test_pluck_single_even_value(self):
        self.assertEqual(pluck([1,2]), [2, 0])

    def test_pluck_multiple_even_values(self):
        self.assertEqual(pluck([5, 0, 3, 0, 4, 2]), [0, 1])

    def test_pluck_no_even_values(self):
        self.assertEqual(pluck([1, 3, 5]), [])

    def test_pluck_odd_values(self):
        self.assertEqual(pluck([1, 3, 5, 7]), [])

    def test_pluck_negative_values(self):
        self.assertEqual(pluck([-2, -4, -6]), [-4, 0])

    def test_pluck_mixed_values(self):
        self.assertEqual(pluck([4, 2, 3, 0, 1]), [0, 3])

if __name__ == '__main__':
    unittest.main()
